
/**
 * The JavaScript API for creating a promise object is this:
 * new Promise((resolve, reject) => {
 *  do async things, then resolve or reject.
 * });
 *
 * Unfortunately, that means that you must know what the async call will be when you
 * create the promise.
 *
 * This class solves that by allowing something to create the promise and subscribe to it
 * without having direct access to the async call that will resolve it.
 *
 * file-1.ts
 * myPromises['promise-1'] = new ExternalResolvePromise();
 * myPromises['promise-1'].then(() => {
 *    //promise resolve logic.
 * });
 *
 * file-2.ts
 * if (myPromises['promise-1'] != null) {
 *    myPromises['promise-1'].externalResolve('payload');
 * }
 */
export class ExternalResolvePromise<T> {

	public externalResolve: (value: T | PromiseLike<T>) => void;

	public externalReject: (reason?: any) => void;

  public promise: Promise<T>;

  private _isResolved: boolean = false;

  private _isRejected: boolean = false;

  get isResolved(): boolean {
    return this._isResolved;
  }

  get isRejected(): boolean {
    return this._isRejected;
  }

	constructor() {

		this.promise = new Promise<T>((resolve, reject) => {
			this.externalResolve = (...args): void => {
        this._isResolved = true;
        resolve(...args);
      };

			this.externalReject = (...args): void => {
        this._isRejected = true;
        reject(...args);
      };
		});
	}



}